package org.mcrf.client

import java.io.File
import org.junit.Assert.*
import org.junit.Test

class BsSitesUiPolishTest {
    @Test fun startupHelpAndFailureMessageMatchCustomSites(){assertTrue(BsSitesPresentation.HELP.contains("также проверяются при открытии MCRF"));assertTrue(BsSitesPresentation.HELP.contains("не меняет текущее подключение"));val s=source("MainActivity");assertTrue(s.contains("Оба выбранных сайта не ответили напрямую"));assertFalse(s.contains("Google и GitLab не ответили напрямую"))}
    @Test fun linkedVkOffersOnlyUnlinkAndUnlinkedOnlyLink(){assertEquals("Отвязать VK",VkAccountPresentation.action(true));assertEquals("Привязать VK",VkAccountPresentation.action(false));val s=source("AndroidDeployUi");assertTrue(s.contains("actions.removeAllViews()"));assertTrue(s.contains("button(VkAccountPresentation.action(linked))"));assertTrue(s.contains("vk.unlink();renderAccountActions()"))}
    private fun source(name:String)=listOf(File("src/main/kotlin/org/mcrf/client/$name.kt"),File("app/src/main/kotlin/org/mcrf/client/$name.kt")).first {it.isFile}.readText()
    @Test fun customSiteStaysSelectedAndAllPresetsRemainAvailable(){val items=BsSitesPresentation.choices("custom.example.org");assertEquals("custom.example.org",items.first());assertEquals(13,items.size);assertTrue(items.containsAll(BsDetectionSites.presets))}
    @Test fun presetSiteIsNotDuplicated(){assertEquals(12,BsSitesPresentation.choices("github.com").size)}
    @Test fun labelsDistinguishPhysicalAndVpnChecks(){assertTrue(BsSitesPresentation.label(0).startsWith("Напрямую"));assertTrue(BsSitesPresentation.label(1).startsWith("Напрямую"));assertTrue(BsSitesPresentation.label(2).startsWith("Через VPN"))}
    @Test fun dropdownIsNotAnEditableTextControl(){val s=source("BsDetectionSitesUi");assertFalse(s.contains("AutoCompleteTextView"));assertTrue(s.contains("val select=picker("));assertTrue(s.contains("iconButton(\"edit\""))}
    @Test fun keyboardOnlyBelongsToPencilDialog(){val s=source("BsDetectionSitesUi");assertTrue(s.contains("tag=\"bs-site-custom-input\""));assertTrue(s.contains("setNegativeButton(\"Отмена\",null)"));assertTrue(s.contains("SOFT_INPUT_STATE_ALWAYS_VISIBLE"));assertEquals(1,Regex("val input=editor").findAll(s).count())}
    @Test fun blockUsesParentSurfaceAndHasExplicitSeparation(){val s=source("BsDetectionSitesUi");assertFalse(s.contains("HomeUiControls.card"));assertFalse(s.contains("background="));assertTrue(s.contains("divider(box,20,0)"));assertTrue(source("ClientTunUi").contains("activity.space(0,20)"))}
    @Test fun choosingOnlyChangesDraftAndExplicitSaveWritesAllSlots(){val s=source("BsDetectionSitesUi");assertTrue(s.contains("selectedListener {position->draft[index]=choices[position]"));assertTrue(s.contains("setTitle(\"Свой сайт"));assertTrue(s.contains("BsDetectionSites.normalize(input.text.toString())"));assertEquals(1,Regex("prefs.edit\\(\\)").findAll(s).count());assertTrue(s.contains("tag=\"bs-sites-save\""))}
    @Test fun helpExplainsBothDirectionsAndLimits(){val h=BsSitesPresentation.HELP;listOf("Два сайта нужны","Если оба не отвечают","хотя бы один","Сайт 3","через выбранный сервер VPN","не в режиме локального прокси","не доказательство блокировки","не меняют DNS").forEach {assertTrue(it,h.contains(it))}}
    @Test fun actualDecisionDoesNotTreatOneDirectSiteFailureAsWholeNetworkLoss(){val r=DirectAccessCheck.Result(DirectAccessCheck.Outcome.RESPONSE,DirectAccessCheck.Outcome.NO_RESPONSE);assertFalse(r.shouldSwitch(true,true,true));assertTrue(r.shouldReturn(true,false))}
    @Test fun bothDirectFailuresOrFailedVpnCheckCanSwitch(){val fail=DirectAccessCheck.Outcome.NO_RESPONSE;val ok=DirectAccessCheck.Outcome.RESPONSE;assertTrue(DirectAccessCheck.Result(fail,fail).shouldSwitch(true,true,true));assertTrue(DirectAccessCheck.Result(ok,ok,fail).shouldSwitch(true,true,true));assertFalse(DirectAccessCheck.Result(ok,ok,fail).shouldSwitch(false,true,true))}
    @Test fun vkHasOneBottomRowAndNoDuplicateAndroidBackButton(){val s=source("VkRelayLoginActivity");assertTrue(s.contains("val actions=LinearLayout"));assertTrue(s.contains("actions.addView(themedButton(\"Другой вход\")"));assertTrue(s.contains("actions.addView(themedButton(\"Обновить\")"));assertFalse(s.contains("themedButton(\"Вернуться"));assertTrue(s.contains("layout.addView(actions,LinearLayout.LayoutParams(-1,-2).apply {topMargin=dp(10)})"))}
    @Test fun vkTopHasReadableGapsAndWebViewKeepsRemainingSpace(){val s=source("VkRelayLoginActivity");assertTrue(s.contains("bottomMargin=dp(8)"));assertTrue(s.contains("bottomMargin=dp(10)"));assertTrue(s.contains("layout.addView(web,LinearLayout.LayoutParams(-1,0,1f))"));assertFalse(s.contains("Открыть VK заново"));assertTrue(s.contains("handler.cancel()"));assertFalse(s.contains("removeAllCookies"))}
}
